import { h } from 'preact';
import { Position } from '../core/types';
import { state } from './state';

export function PositionCard({ position }: { position: Position | null }) {
  if (!position) return null;

  const currentPrice = state.indicators.value.ema9; // Simplified current price
  const pnl = position.side === 'LONG' 
    ? (currentPrice - position.entryPrice) * position.qty 
    : (position.entryPrice - currentPrice) * position.qty;

  return (
    <div className="surface" style={{ padding: '16px', marginBottom: '20px', borderLeft: `4px solid ${position.side === 'LONG' ? 'var(--color-green)' : 'var(--color-red)'}` }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
        <span style={{ fontWeight: 'bold', fontSize: '18px' }}>{position.side} {position.symbol}</span>
        <span style={{ color: pnl >= 0 ? 'var(--color-green)' : 'var(--color-red)', fontWeight: 'bold', className: 'tabular-nums' }}>
          {pnl >= 0 ? '+' : ''}{pnl.toFixed(2)}
        </span>
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px', fontSize: '14px', color: 'var(--text-muted)' }}>
        <div>Entry: <span className="tabular-nums" style={{ color: 'white' }}>{position.entryPrice.toFixed(2)}</span></div>
        <div>Mark: <span className="tabular-nums" style={{ color: 'white' }}>{currentPrice.toFixed(2)}</span></div>
        <div>SL: <span className="tabular-nums" style={{ color: 'var(--color-red)' }}>{position.stopLoss.toFixed(2)}</span></div>
        <div>TP: <span className="tabular-nums" style={{ color: 'var(--color-green)' }}>{position.takeProfit.toFixed(2)}</span></div>
      </div>
    </div>
  );
}
